class Program
{
    static void Check(bool ok,string text){if(!ok)throw new Exception(text);}
    static void Set(object o,string field,object? value)=>o.GetType().GetField(field,BindingFlags.NonPublic|BindingFlags.Instance)!.SetValue(o,value);
    static T Get<T>(object o,string field)=>(T)o.GetType().GetField(field,BindingFlags.NonPublic|BindingFlags.Instance)!.GetValue(o)!;
    static object? Call(object o,string method,params object?[] args)=>o.GetType().GetMethod(method,BindingFlags.NonPublic|BindingFlags.Instance|BindingFlags.DeclaredOnly)!.Invoke(o,args);
    static Package Fixture(string dir,bool selective=false)
    {
        var folder=Path.Combine(dir,"input","GeneratedGame");Directory.CreateDirectory(Path.Combine(folder,"Data"));Directory.CreateDirectory(Path.Combine(folder,"Extras"));
        File.WriteAllText(Path.Combine(folder,"Game.exe"),"harmless generated fixture; never execute");File.WriteAllBytes(Path.Combine(folder,"Data","large.bin"),Enumerable.Range(0,1536*1024).Select(i=>(byte)(i%251)).ToArray());File.WriteAllText(Path.Combine(folder,"Extras","guide.txt"),"kept or moved according to selection");
        var p=new Package{Id=Guid.NewGuid().ToString("N"),IsReal=true,Registered=false,Source=folder,DetectedRoot=folder,SearchRoot=Path.Combine(dir,"input"),Name="GeneratedGame",Folder="GeneratedGame",Alias="가상 게임"};if(selective)p.OmittedFolders.Add("Extras");return p;
    }
    static MainWindow Window(string dir,out Package p)
    {
        p=Fixture(dir);var scan=GameScanner.Scan(p.SearchRoot);scan.PrepareIndex();var plan=new WorkspaceDocument{SearchRoot=p.SearchRoot,SearchLocations=[new(){Path=p.SearchRoot}],Destination=Path.Combine(dir,"library"),BackupRoot=Path.Combine(dir,"backups"),Packages=[p],Checkpoints=[WorkspaceReconciler.Capture(p,scan)]};var store=new WorkspaceStore(Path.Combine(dir,"data","workspace.json"));store.Save(plan);
        var w=new MainWindow();new System.Windows.Interop.WindowInteropHelper(w).EnsureHandle();Set(w,"workspaceStore",store);Set(w,"workspaceLock",store.AcquireLock());Call(w,"ApplyWorkspace",plan);Set(w,"snapshot",scan);Set(w,"sessionReady",true);Set(w,"playerRoot",plan.Destination);Set(w,"playerDocument",new PlayerDocument());Set(w,"directEngineFactory",(Func<BackupEngine>)(()=>new(Path.Combine(dir,"records"))));return w;
    }
    static void Close(MainWindow w){Set(w,"closingWithoutSave",true);w.Close();}
    static IEnumerable<DependencyObject> Logical(DependencyObject root){yield return root;foreach(var child in LogicalTreeHelper.GetChildren(root).OfType<DependencyObject>())foreach(var nested in Logical(child))yield return nested;}
    static void Wait(Task task){var frame=new DispatcherFrame();task.ContinueWith(_=>Application.Current.Dispatcher.BeginInvoke(new Action(()=>frame.Continue=false)));Dispatcher.PushFrame(frame);task.GetAwaiter().GetResult();}
    static void Click(Button b)=>b.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));
    static void Toggle(System.Windows.Controls.Primitives.ToggleButton b,bool value){b.IsChecked=value;b.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));}
    static Button FindButton(Window w,string text)=>Logical((DependencyObject)w.Content).OfType<Button>().Single(b=>b.Content as string==text);
    static T Named<T>(Window w,string name)where T:FrameworkElement=>Logical((DependencyObject)w.Content).OfType<T>().Single(e=>e.Name==name);
    static void Layout(Window w,double width,double height,string file){var body=(FrameworkElement)w.Content;body.Measure(new Size(width,height));body.Arrange(new Rect(0,0,width,height));body.UpdateLayout();foreach(var b in Logical(body).OfType<Button>().Where(b=>b.IsVisible||b.ActualWidth>0)){var point=b.TranslatePoint(new Point(),body);Check(point.X>=-1&&point.X+b.ActualWidth<=width+1,"Button clipped horizontally: "+b.Content);}var bitmap=new RenderTargetBitmap((int)width,(int)height,96,96,PixelFormats.Pbgra32);var bg=new DrawingVisual();using(var draw=bg.RenderOpen())draw.DrawRectangle(w.Background,null,new Rect(0,0,width,height));bitmap.Render(bg);bitmap.Render(body);var png=new PngBitmapEncoder();png.Frames.Add(BitmapFrame.Create(bitmap));using var output=File.Create(file);png.Save(output);}
    static Package Second(MainWindow w,string dir){var p=Fixture(Path.Combine(dir,"second"));p.Alias="두 번째 가상 게임";Get<List<Package>>(w,"packages").Add(p);var scan=GameScanner.Scan(dir);Set(w,"snapshot",scan);Set(w,"checkpoints",Get<List<Package>>(w,"packages").Select(g=>WorkspaceReconciler.Capture(g,scan)).ToList());return p;}
    static IntakeSelection Plan(MainWindow w,List<Package> games)=>new(new MoveSelection(games,Get<List<Package>>(w,"packages")));
    static LibraryDocument Registered(Package p)=>new(){Games=[new(){Id=p.Id,Folder=p.Folder,LastKnownPath=p.Source,Executables=["Game.exe"]}]};
    static (Package Game,string Parent,string Search,ScanSnapshot Scan,FolderCheckpoint Checkpoint) Game(string dir,bool marked=true)
    {
        var search=Path.Combine(dir,"container");var parent=Path.Combine(search,"外側パッケージ","ゲーム名");var data=Path.Combine(parent,"data");Directory.CreateDirectory(data);File.WriteAllText(Path.Combine(data,"Game.exe"),"harmless generated fixture; never execute");File.WriteAllText(Path.Combine(data,"save.dat"),"test save");
        var p=new Package{Id=Guid.NewGuid().ToString("N"),IsReal=true,Registered=marked,Source=data,DetectedRoot=data,SearchRoot=search,Name="data",Folder="data"};if(marked)LibraryStore.EnsureIdentity(data,p.Id);var scan=GameScanner.Scan(search);scan.SearchRoots.Add(search);scan.PrepareIndex();return(p,parent,search,scan,WorkspaceReconciler.Capture(p,scan));
    }
    static string RenameParent(string parent){var renamed=Path.Combine(Path.GetDirectoryName(parent)!,"ゲーム名5555");Directory.Move(parent,renamed);return Path.Combine(renamed,"data");}
    static string Refusal(Action run){try{run();}catch(IOException e){return e.Message;}throw new Exception("Expected refusal");}

    static Package Pending(string path,string search)=>new(){Id=Guid.NewGuid().ToString("N"),IsReal=true,Registered=false,Source=path,DetectedRoot=path,SearchRoot=search,Name=Path.GetFileName(path),Folder=Path.GetFileName(path)};
    static (ScanSnapshot Scan,Package Parent,Package Child) Dependencies(string dir,bool tool=false)
    {
        var search=Path.Combine(dir,"Input");var parent=Path.Combine(search,"StandaloneGame");var child=Path.Combine(parent,"engine");Directory.CreateDirectory(Path.Combine(child,"assets"));
        var probe=Path.GetFullPath("tests/DependencyProbe/bin/Debug/net10.0-windows");foreach(var file in Directory.GetFiles(probe))File.Copy(file,Path.Combine(parent,Path.GetFileName(file)),true);
        File.WriteAllText(Path.Combine(child,"Engine.exe"),"generated engine helper metadata; never execute");File.WriteAllText(Path.Combine(child,"assets","required.dat"),"generated required data");File.WriteAllText(Path.Combine(parent,"readme.txt"),"generated readme");if(tool)File.WriteAllText(Path.Combine(search,"Tool.exe"),"generated root tool");
        var scan=GameScanner.Scan(search);scan.SearchRoots.Add(search);var prepared=ScanPreparation.Build(scan,[],[],[],Path.Combine(dir,"library"),CancellationToken.None);return(scan,prepared.Packages.Single(p=>p.Source==parent),prepared.Packages.Single(p=>p.Source==child));
    }
    static int Probe(string folder,string result)
    {var info=new System.Diagnostics.ProcessStartInfo(Path.Combine(folder,"DependencyProbe.exe")){UseShellExecute=false,CreateNoWindow=true,WorkingDirectory=folder};info.ArgumentList.Add(result);using var process=System.Diagnostics.Process.Start(info)!;Check(process.WaitForExit(10000),"Probe did not exit");return process.ExitCode;}
    static List<Package> All(ScanSnapshot scan,string dir)=>ScanPreparation.Build(scan,[],[],[],Path.Combine(dir,"library"),CancellationToken.None).Packages;
    static bool Answer(Action action,string label,string? screenshot=null)
    {
        bool shown=false;Exception? error=null;var timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(30)};timer.Tick+=(_,_)=>{var dialog=Application.Current.Windows.OfType<AppDialog>().FirstOrDefault();if(dialog==null)return;timer.Stop();try{shown=true;if(screenshot!=null){Logical((DependencyObject)dialog.Content).OfType<Expander>().ToList().ForEach(e=>e.IsExpanded=true);Layout(dialog,680,470,screenshot);}dialog.ActionButtons.Single(b=>b.Content is TextBlock t&&t.Text==label).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));}catch(Exception ex){error=ex;dialog.Close();}};timer.Start();try{action();}finally{timer.Stop();}if(error!=null)throw error;return shown;
    }
    static void Bind(MainWindow w,List<Package> games,ScanSnapshot scan,string dir){Set(w,"projectRoot",dir);Set(w,"packages",games);Set(w,"snapshot",scan);Set(w,"selected",games[0]);Set(w,"checkpoints",games.Select(p=>WorkspaceReconciler.Capture(p,scan)).ToList());}
    [STAThread]static int Main(string[] args)
    {
        var root=Path.GetFullPath(args[0]);Directory.CreateDirectory(root);var results=new List<object>();int failed=0;var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};var styles=XDocument.Load(Path.Combine(AppContext.BaseDirectory,"styles-source.xaml")).Root!.Elements().Single().Elements().Single();app.Resources=(ResourceDictionary)XamlReader.Parse(styles.ToString(),new ParserContext{BaseUri=new Uri(AppContext.BaseDirectory)});SynchronizationContext.SetSynchronizationContext(new DispatcherSynchronizationContext());
        void Test(string name,Action<string> action){try{var dir=Path.Combine(root,name);Directory.CreateDirectory(dir);action(dir);results.Add(new{name,passed=true});Console.WriteLine("PASS "+name);}catch(Exception ex){failed++;results.Add(new{name,passed=false,error=ex.ToString()});Console.WriteLine("FAIL "+name+" "+ex.Message);}}
        Test("parent-and-child-executables-are-observations-without-automatic-exclusions",dir=>{var f=Dependencies(dir,true);var games=All(f.Scan,dir);Check(games.Count==3&&games.All(p=>p.OmittedFolders.Count==0&&p.CandidateOmissions.Count==0)&&f.Parent.Includes(f.Child.Source),"Nested executable changed physical scope");});
        Test("backup-parent-includes-required-child-data",dir=>{var f=Dependencies(dir);var e=new BackupEngine(Path.Combine(dir,"backups"));var job=Task.Run(()=>e.CreateAsync(f.Parent,[])).GetAwaiter().GetResult();Check(job.Files.Any(f=>f.RelativePath==Path.Combine("engine","Engine.exe"))&&job.Files.Any(f=>f.RelativePath==Path.Combine("engine","assets","required.dat")),"Required child files missing from backup");});
        Test("real-dependent-executable-runs-after-backup-move-and-undo",dir=>{var f=Dependencies(dir);var e=new BackupEngine(Path.Combine(dir,"backups"));Check(Probe(f.Parent.Source,Path.Combine(dir,"before.txt"))==0,"Probe was invalid before move");var job=Task.Run(()=>e.CreateAsync(f.Parent,[])).GetAwaiter().GetResult();var move=Task.Run(()=>e.MoveAsync(job.Id,Path.Combine(dir,"target","MovedGame"))).GetAwaiter().GetResult();Check(Probe(move.Destination,Path.Combine(dir,"after.txt"))==0&&!Directory.Exists(f.Parent.Source),"Move omitted required child files");Task.Run(()=>e.UndoMoveAsync(job.Id,move.Id)).GetAwaiter().GetResult();Check(Probe(f.Parent.Source,Path.Combine(dir,"undo.txt"))==0,"Undo did not restore complete tree");});
        Test("real-dependent-executable-runs-after-direct-move",dir=>{var f=Dependencies(dir);var e=new BackupEngine(Path.Combine(dir,"records"));var job=Task.Run(()=>e.PrepareDirectMoveAsync(f.Parent,[])).GetAwaiter().GetResult();var move=Task.Run(()=>e.MoveAsync(job.Id,Path.Combine(dir,"target","MovedGame"))).GetAwaiter().GetResult();Check(Probe(move.Destination,Path.Combine(dir,"result.txt"))==0&&!Directory.Exists(f.Parent.Source),"Direct move lost dependency tree");});
        Test("probe-fails-when-required-data-is-deliberately-removed",dir=>{var f=Dependencies(dir);File.Delete(Path.Combine(f.Child.Source,"assets","required.dat"));Check(Probe(f.Parent.Source,Path.Combine(dir,"must-not-exist.txt"))==7&&!File.Exists(Path.Combine(dir,"must-not-exist.txt")),"Probe would hide a missing dependency");});
        Test("explicit-user-exclusion-is-preserved",dir=>{var f=Dependencies(dir);f.Parent.OmittedFolders.Add("engine");f.Parent.Contents.Add(new(){Path="engine",Role="exclude",Id=f.Child.Id});FolderPolicy.RestoreAutomaticExclusions(f.Parent);var e=new BackupEngine(Path.Combine(dir,"backups"));var job=Task.Run(()=>e.CreateAsync(f.Parent,[])).GetAwaiter().GetResult();Check(!job.Files.Any(f=>f.RelativePath.StartsWith("engine\\",StringComparison.OrdinalIgnoreCase)),"Explicit user exclusion was overridden");});
        Test("legacy-unregistered-automatic-exclusion-is-removed",dir=>{var f=Dependencies(dir);f.Parent.OmittedFolders.Add("engine");f.Parent.CandidateOmissions.Add("engine");var alias="기존 별칭";f.Parent.Alias=alias;FolderPolicy.RestoreAutomaticExclusions(new List<Package>{f.Parent,f.Child});Check(f.Parent.Includes(f.Child.Source)&&f.Parent.CandidateOmissions.Count==0&&f.Parent.Alias==alias,"Legacy automatic omission remained");});
        Test("legacy-registered-automatic-exclusion-is-removed-without-changing-id",dir=>{var f=Dependencies(dir);LibraryStore.EnsureIdentity(f.Parent.Source,f.Parent.Id);f.Parent.Registered=true;f.Parent.OmittedFolders.Add("engine");f.Parent.CandidateOmissions.Add("engine");var marker=File.ReadAllBytes(Path.Combine(f.Parent.Source,LibraryStore.MarkerName));FolderPolicy.RestoreAutomaticExclusions(new List<Package>{f.Parent,f.Child});Check(f.Parent.Includes(f.Child.Source)&&marker.SequenceEqual(File.ReadAllBytes(Path.Combine(f.Parent.Source,LibraryStore.MarkerName))),"Registered dependency exclusion or ID changed");});
        Test("explicit-choice-wins-over-legacy-inferred-path",dir=>{var f=Dependencies(dir);f.Parent.OmittedFolders.Add("engine");f.Parent.CandidateOmissions.Add("engine");f.Parent.Contents.Add(new(){Path="engine",Role="game",Id=f.Child.Id});f.Child.CompositionParentId=f.Parent.Id;FolderPolicy.RestoreAutomaticExclusions(new List<Package>{f.Parent,f.Child});Check(!f.Parent.Includes(f.Child.Source)&&f.Child.CompositionParentId==f.Parent.Id,"Explicit separate-game choice was lost");});
        Test("legacy-inferred-parent-link-is-cleared",dir=>{var f=Dependencies(dir);f.Parent.OmittedFolders.Add("engine");f.Parent.CandidateOmissions.Add("engine");f.Child.CompositionParentId=f.Parent.Id;FolderPolicy.RestoreAutomaticExclusions(new List<Package>{f.Parent,f.Child});Check(f.Child.CompositionParentId==""&&f.Parent.Includes(f.Child.Source),"Automatic separate-game link survived");});
        Test("new-backup-restores-legacy-automatic-exclusions-before-capture",dir=>{var f=Dependencies(dir);f.Parent.OmittedFolders.Add("engine");f.Parent.CandidateOmissions.Add("engine");var e=new BackupEngine(Path.Combine(dir,"backups"));var job=Task.Run(()=>e.CreateAsync(f.Parent,[])).GetAwaiter().GetResult();Check(job.Files.Any(f=>f.RelativePath==Path.Combine("engine","assets","required.dat"))&&job.Package.CandidateOmissions.Count==0,"New backup repeated old automatic omission");});
        Test("new-direct-move-restores-legacy-exclusions-before-capture",dir=>{var f=Dependencies(dir);f.Parent.OmittedFolders.Add("engine");f.Parent.CandidateOmissions.Add("engine");var e=new BackupEngine(Path.Combine(dir,"records"));var job=Task.Run(()=>e.PrepareDirectMoveAsync(f.Parent,[])).GetAwaiter().GetResult();Check(job.Files.Any(f=>f.RelativePath==Path.Combine("engine","assets","required.dat"))&&job.Package.OmittedFolders.Count==0,"Direct move repeated old omission");});
        Test("parent-registration-absorbs-only-unedited-child-candidates",dir=>{var w=Window(dir,out _);try{var f=Dependencies(dir);var games=new List<Package>{f.Parent,f.Child};Bind(w,games,f.Scan,dir);Set(w,"destination",Path.Combine(dir,"library"));Check((bool)Call(w,"RegisterGame",f.Parent,true)!,"Parent registration failed");Check(games.Count==1&&!File.Exists(Path.Combine(f.Child.Source,LibraryStore.MarkerName))&&Directory.Exists(f.Child.Source),"Child was registered or removed physically");}finally{Close(w);}});
        Test("child-registration-does-not-silently-register-its-parent",dir=>{var f=Dependencies(dir);GameRegistration.Add(f.Child,[],f.Scan,Path.Combine(dir,"library"),false);Check(LibraryStore.ReadIdentity(f.Child.Source)?.GameId==f.Child.Id&&!File.Exists(Path.Combine(f.Parent.Source,LibraryStore.MarkerName)),"Child registration changed parent");});
        Test("parent-plus-child-selection-is-one-complete-parent-plan",dir=>{var w=Window(dir,out _);try{var f=Dependencies(dir);Bind(w,new(){f.Parent,f.Child},f.Scan,dir);var picked=new List<Package>{f.Parent,f.Child};bool allowed=false;Check(Answer(()=>allowed=(bool)Call(w,"ConfirmParentScopes",picked)!,"폴더 전체로 진행"),"Confirmation absent");Check(allowed&&picked.Count==1&&picked[0].Id==f.Parent.Id&&picked[0].Includes(f.Child.Source),"Nested selection was split or moved twice");}finally{Close(w);}});
        Test("cancel-whole-parent-confirmation-keeps-selection-and-files",dir=>{var w=Window(dir,out _);try{var f=Dependencies(dir);Bind(w,new(){f.Parent,f.Child},f.Scan,dir);var picked=new List<Package>{f.Parent,f.Child};bool allowed=true;Answer(()=>allowed=(bool)Call(w,"ConfirmParentScopes",picked)!,"취소");Check(!allowed&&picked.Count==2&&f.Parent.OmittedFolders.Count==0&&Directory.Exists(f.Child.Source),"Cancel mutated selection or files");}finally{Close(w);}});
        Test("configured-child-is-not-silently-absorbed",dir=>{var w=Window(dir,out _);try{var f=Dependencies(dir);f.Child.Alias="보존할 정보";Bind(w,new(){f.Parent,f.Child},f.Scan,dir);var picked=new List<Package>{f.Parent};bool allowed=true;Answer(()=>allowed=(bool)Call(w,"ConfirmParentScopes",picked)!,"확인");Check(!allowed&&f.Child.Alias=="보존할 정보"&&Get<List<Package>>(w,"packages").Count==2,"Configured child metadata lost");}finally{Close(w);}});
        Test("search-root-exe-does-not-hide-candidates-or-skip-confirmation",dir=>{var w=Window(dir,out _);try{var f=Dependencies(dir,true);var games=All(f.Scan,dir);Bind(w,games,f.Scan,dir);var parent=games.Single(p=>p.Source==f.Scan.Root);var picked=new List<Package>{parent};bool allowed=false;Check(Answer(()=>allowed=(bool)Call(w,"ConfirmParentScopes",picked)!,"폴더 전체로 진행",Path.Combine(root,"whole-folder-confirmation.png")),"Search-root scope was silently accepted");Check(allowed&&games.Any(p=>p.Source==f.Parent.Source)&&games.Any(p=>p.Source==f.Child.Source)&&parent.Includes(f.Child.Source),"Search root hid children or excluded dependencies");}finally{Close(w);}});
        Test("explicitly-separated-registered-child-is-outside-parent-plan",dir=>{var w=Window(dir,out _);try{var f=Dependencies(dir);f.Parent.OmittedFolders.Add("engine");f.Parent.Contents.Add(new(){Id=f.Child.Id,Path="engine",Role="game"});f.Child.Registered=true;Bind(w,new(){f.Parent,f.Child},f.Scan,dir);Check((bool)Call(w,"ConfirmParentScopes",new List<Package>{f.Parent})!&&!f.Parent.Includes(f.Child.Source),"Explicit separation was ignored");}finally{Close(w);}});
        Test("two-thousand-candidates-are-visible-without-file-exclusion",dir=>{var search=Path.Combine(dir,"Input");var scan=new ScanSnapshot{Root=search};scan.SearchRoots.Add(search);scan.Directories.Add(search);scan.Files.Add(new(Path.Combine(search,"Tool.exe"),1,DateTime.UtcNow));for(int i=0;i<2000;i++){var path=Path.Combine(search,"Game"+i.ToString("D4"));scan.Directories.Add(path);scan.Files.Add(new(Path.Combine(path,"Game.exe"),1,DateTime.UtcNow));}var found=All(scan,dir);Check(found.Count==2001&&found.All(p=>p.OmittedFolders.Count==0),"Detection decided physical exclusions");});
        Test("readme-parent-can-be-selected-beside-unowned-root-tool",dir=>{var w=Window(dir,out _);try{var f=Dependencies(dir,true);var games=All(f.Scan,dir);Bind(w,games,f.Scan,dir);var child=games.Single(p=>p.Source==f.Child.Source);Set(w,"selected",child);Call(w,"SetScope",f.Parent.Source,true);Check(child.Source==f.Parent.Source&&child.Includes(Path.Combine(f.Parent.Source,"readme.txt"))&&child.OmittedFolders.Count==0,"Readme parent was blocked or incomplete");Call(w,"Render");Layout(w,1200,800,Path.Combine(root,"complete-parent-scope.png"));}finally{Close(w);}});
        Test("old-automatic-exclusion-journal-is-not-resumed-forward",dir=>{var f=Dependencies(dir);f.Parent.OmittedFolders.Add("engine");var e=new BackupEngine(Path.Combine(dir,"backups"));var job=Task.Run(()=>e.CreateAsync(f.Parent,[])).GetAwaiter().GetResult();job.Package.CandidateOmissions.Add("engine");File.WriteAllText(Path.Combine(e.Root,job.Id,"manifest.json"),JsonSerializer.Serialize(job));bool denied=false;try{Task.Run(()=>e.MoveAsync(job.Id,Path.Combine(dir,"target","Moved"))).GetAwaiter().GetResult();}catch(IOException ex){denied=ex.Message.Contains("자동 제외");}Check(denied&&Probe(f.Parent.Source,Path.Combine(dir,"still-ready.txt"))==0&&!Directory.Exists(Path.Combine(dir,"target","Moved")),"Legacy partial scope was resumed");});
        Test("old-completed-partial-move-can-be-undone-to-restore-launch",dir=>{var f=Dependencies(dir);f.Parent.OmittedFolders.Add("engine");var e=new BackupEngine(Path.Combine(dir,"backups"));var job=Task.Run(()=>e.CreateAsync(f.Parent,[])).GetAwaiter().GetResult();var move=Task.Run(()=>e.MoveAsync(job.Id,Path.Combine(dir,"target","Moved"))).GetAwaiter().GetResult();Check(Probe(move.Destination,Path.Combine(dir,"must-fail.txt"))==7,"Legacy fixture did not model missing dependencies");job=e.Load(job.Id);job.Package.CandidateOmissions.Add("engine");File.WriteAllText(Path.Combine(e.Root,job.Id,"manifest.json"),JsonSerializer.Serialize(job));Task.Run(()=>e.UndoMoveAsync(job.Id,move.Id)).GetAwaiter().GetResult();Check(Probe(f.Parent.Source,Path.Combine(dir,"restored.txt"))==0,"Legacy rollback did not reunite required data");});
        Test("composition-main-includes-child-executables-unless-explicitly-excluded",dir=>{var f=Dependencies(dir);Check(CompositionPlan.Role(f.Parent,f.Child.Source)=="main"&&f.Parent.Includes(f.Child.Source),"EXE created an implicit separate-game role");CompositionPlan.Assign(f.Parent,f.Child.Source,"exclude",new(),f.Scan);Check(!f.Parent.Includes(f.Child.Source),"Explicit exclusion not applied");CompositionPlan.Assign(f.Parent,f.Child.Source,"main",new(),f.Scan);Check(f.Parent.Includes(f.Child.Source),"Explicit main inclusion rejected");});
        Test("registered-nested-entry-follows-parent-move-and-undo",dir=>{var w=Window(dir,out _);try{var f=Dependencies(dir);f.Parent.OmittedFolders.Add("engine");f.Parent.CandidateOmissions.Add("engine");GameRegistration.Add(f.Parent,[],f.Scan,Path.Combine(dir,"library"),false);f.Parent.Registered=true;f.Child.CompositionParentId=f.Parent.Id;f.Child.Alias="기존 하위 항목";f.Child.Genres=["보존할 장르"];GameRegistration.Add(f.Child,[],GameScanner.Scan(f.Scan.Root),Path.Combine(dir,"library"),false);f.Child.Registered=true;FolderPolicy.RestoreAutomaticExclusions(new List<Package>{f.Parent,f.Child});var scan=GameScanner.Scan(f.Scan.Root);var old=f.Parent.Source;var oldChild=f.Child.Source;Bind(w,new(){f.Parent,f.Child},scan,dir);Set(w,"destination",Path.Combine(dir,"library"));Set(w,"backupStorageRoot",Path.Combine(dir,"backups"));Set(w,"libraryDocument",new LibraryStore(Path.Combine(dir,"library")).Load());Set(w,"playerDocument",new PlayerDocument{Games=[new(){Id=f.Child.Id,Favorite=true,Arguments="--keep"}]});var timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(30)};timer.Tick+=(_,_)=>{foreach(var dialog in app.Windows.OfType<AppDialog>().ToList())dialog.Close();};timer.Start();try{Wait((Task)Call(w,"ExecuteMoveListAsync",new List<Package>{f.Parent},Path.Combine(dir,"library"))!);}finally{timer.Stop();}Check(f.Parent.Source!=old&&f.Child.Source==Path.Combine(f.Parent.Source,"engine")&&Probe(f.Parent.Source,Path.Combine(dir,"moved.txt"))==0,"Registered child did not follow complete parent tree");Check(f.Child.Alias=="기존 하위 항목"&&f.Child.Genres.SequenceEqual(new[]{"보존할 장르"})&&Get<PlayerDocument>(w,"playerDocument").Games.Single(g=>g.Id==f.Child.Id).Favorite,"Nested metadata changed");var e=new BackupEngine(Path.Combine(dir,"backups"));var move=e.ListMoves().Single();var job=e.Load(move.BackupId);var undone=Task.Run(()=>e.UndoMoveAsync(job.Id,move.Id)).GetAwaiter().GetResult();var observed=GameScanner.Scan(old);Call(w,"ApplyObservedMove",job,undone,observed,null);Check(f.Parent.Source==old&&f.Child.Source==oldChild&&Probe(old,Path.Combine(dir,"undo.txt"))==0,"Nested paths did not follow parent rollback");}finally{Close(w);}});
        Test("legacy-ui-rollback-does-not-reintroduce-automatic-exclusions",dir=>{var w=Window(dir,out _);try{var f=Dependencies(dir);GameRegistration.Add(f.Parent,[],f.Scan,Path.Combine(dir,"library"),false);f.Parent.Registered=true;f.Parent.OmittedFolders.Add("engine");var e=new BackupEngine(Path.Combine(dir,"backups"));var job=Task.Run(()=>e.CreateAsync(f.Parent,[])).GetAwaiter().GetResult();var move=Task.Run(()=>e.MoveAsync(job.Id,Path.Combine(dir,"target","Moved"))).GetAwaiter().GetResult();job=e.Load(job.Id);job.Package.CandidateOmissions.Add("engine");File.WriteAllText(Path.Combine(e.Root,job.Id,"manifest.json"),JsonSerializer.Serialize(job));var original=f.Parent.Source;f.Parent.RestoreAutomaticExclusions();Bind(w,new(){f.Parent,f.Child},f.Scan,dir);Call(w,"ApplyObservedMove",job,move,GameScanner.Scan(move.Destination),null);var undone=Task.Run(()=>e.UndoMoveAsync(job.Id,move.Id)).GetAwaiter().GetResult();Call(w,"ApplyObservedMove",job,undone,GameScanner.Scan(original),null);Check(f.Parent.Source==original&&f.Parent.OmittedFolders.Count==0&&f.Parent.CandidateOmissions.Count==0&&f.Parent.Includes(f.Child.Source)&&Probe(original,Path.Combine(dir,"restored.txt"))==0,"UI rollback restored the unsafe old exclusion");Check(Get<List<FolderCheckpoint>>(w,"checkpoints").Single(c=>c.PackageId==f.Parent.Id).Files.Any(f=>f.RelativePath==Path.Combine("engine","assets","required.dat")),"Restored checkpoint omitted required data");}finally{Close(w);}});

        File.WriteAllText(args[1],JsonSerializer.Serialize(new{total=results.Count,passed=results.Count-failed,failed,results},new JsonSerializerOptions{WriteIndented=true}));return failed==0?0:1;
